1	/* ===== Dù lượn, đi dạo và lái xe nhiều người: máy trạng thái phiên (không DOM, không three) =====
2	   Một phiên thuộc một loại (kind): 'fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe. Ba nhóm 5 slot riêng; peers là nhóm cùng loại với mình
3	   (dùng cho đầy chỗ, chọn người xem, lời mời). Phase 'flying' nghĩa là "đang giữ chỗ" cho mọi loại (đi dạo, lái xe cũng vậy). */
4	import type { Flyer, Kind, ServerMsg } from './protocol';
5	import type { Transport } from './client';
6	import { multiParams } from './params';
7	
8	export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
9	export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';
10	
11	export class MultiSession {
12	  phase: Phase = 'connecting';
13	  flyers: Flyer[] = [];
14	  walkers: Flyer[] = [];   // người đi dạo (lobby.walkers); máy chủ cũ không gửi
15	  drivers: Flyer[] = [];   // người lái xe (lobby.drivers); máy chủ cũ không gửi
16	  mySlot = -1;
17	  watched = -1;       // slot đang xem (trong nhóm cùng loại), -1 = không ai
18	  invite = false;     // đang xem và còn chỗ trống
19	  notice: Notice = '';
20	  name = '';
21	  ch = 0;             // nhân vật mình chọn (0 nam, 1 nữ); gửi kèm join kind 'walk' và join xe máy (sảnh và lời mời đều qua join())
22	  veh = 0;            // loại xe của phiên 'drive': 0 ô tô (gói join như khách cũ), 1 xe máy (join kèm veh + ch; máy chủ phải vọng veh trong joined)
23	  onChange: () => void = () => {};
24	  onPos: (f: number[][]) => void = () => {};
25	  onWalkPos: (w: number[][]) => void = () => {};
26	  peersDrive: (d: number[][]) => void = () => {};   // nhóm d của gói pos (mẫu onWalkPos): mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]
27	  private t: Transport | null = null;
28	  private disposed = false;
29	  private first = true; // chưa nhận lobby nào
30	
31	  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n), readonly kind: Kind = 'fly') {}
32	
33	  /* Danh sách cùng loại với mình */
34	  get peers(): Flyer[] { return this.kind === 'walk' ? this.walkers : this.kind === 'drive' ? this.drivers : this.flyers; }
35	
36	  /* Số chỗ của nhóm cùng loại */
37	  private get cap(): number { return this.kind === 'walk' ? multiParams.stroll.slots : this.kind === 'drive' ? multiParams.drive.slots : multiParams.slots; }
38	
39	  open(): void {
40	    this.connect().then(t => {
41	      if (this.disposed) { t.close(); return; }
42	      this.t = t;
43	      t.onMessage = m => this.recv(m);
44	      t.onClose = () => this.lost();
45	    }, () => {
46	      if (this.disposed) return;
47	      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
48	    });
49	  }
50	
51	  /* Người lái chỉ xin chỗ sau khi lobby đầu đã có drivers: máy chủ cũ (main trước D-034) coi join kind 'drive' là join bay và cho chiếm một chỗ bay */
52	  join(name: string): void {
53	    this.name = name; this.notice = '';
54	    if (this.kind === 'drive' && this.first) return;
55	    this.t?.send(this.kind === 'fly' ? { t: 'join', name } : this.kind === 'walk' ? { t: 'join', name, kind: 'walk', ch: this.ch }
56	      : this.veh === 1 ? { t: 'join', name, kind: 'drive', ch: this.ch, veh: 1 } : { t: 'join', name, kind: this.kind });
57	  }
58	
59	  // Rời chỗ (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
60	  leave(): void {
61	    if (this.phase !== 'flying') return;
62	    this.t?.send({ t: 'leave' });
63	    this.notice = 'released'; this.toWatching();
64	    this.onChange();
65	  }
66	
67	  // ts: giờ gửi (ms, đồng hồ của khách này) để người xem đặt mẫu theo trục giờ người gửi
68	  sendPos(x: number, y: number, z: number, yaw: number, bank: number, ts: number): void {
69	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank, ts });
70	  }
71	
72	  // Người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh) thay cho bank
73	  sendWalk(x: number, y: number, z: number, yaw: number, pose: number, ts: number): void {
74	    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, pose, ts });
75	  }
76	
77	  // Người lái: v tốc độ có dấu (m/s), st góc lái (rad) thay cho bank / pose; ts giờ gửi (ms, đồng hồ khách này), không truyền thì lấy performance.now()
78	  sendDrive(p: { x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }): void {
79	    if (this.phase !== 'flying') return;
80	    const ts = typeof p.ts === 'number' ? p.ts : Math.round(performance.now());
81	    this.t?.send({ t: 'pos', x: p.x, y: p.y, z: p.z, yaw: p.yaw, v: p.v, st: p.st, ts });
82	  }
83	
84	  heartbeat(): void {
85	    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
86	  }
87	
88	  dispose(): void {
89	    this.disposed = true;
90	    this.t?.close(); this.t = null;
91	  }
92	
93	  private toWatching(): void {
94	    this.phase = 'watching'; this.mySlot = -1;
95	    if (this.kind === 'walk') this.walkers = this.walkers.filter(f => f.slot !== this.mySlotWas);
96	    else if (this.kind === 'drive') this.drivers = this.drivers.filter(f => f.slot !== this.mySlotWas);
97	    else this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
98	    this.fixWatched();
99	  }
100	  private mySlotWas = -1;
101	
102	  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác (cùng loại)
103	  private fixWatched(): void {
104	    const ids = this.peers.map(f => f.slot);
105	    if (this.phase === 'watching') {
106	      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
107	      this.invite = ids.length < this.cap;
108	    } else { this.watched = -1; this.invite = false; }
109	  }
110	
111	  private lost(): void {
112	    if (this.disposed) return;
113	    this.phase = 'solo'; this.notice = 'lost';
114	    this.flyers = []; this.walkers = []; this.drivers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
115	    this.t = null; this.onChange();
116	  }
117	
118	  /* Máy chủ cũ (lobby đầu không có walkers / drivers, hoặc joined xe máy không vọng veh) không biết chỗ đi dạo / lái xe / xe máy: đóng kết nối, đi / lái một mình như khi không kết nối được */
119	  private offline(): void {
120	    const t = this.t;
121	    this.t = null;
122	    if (t) { t.onClose = () => {}; t.onMessage = () => {}; t.close(); }
123	    this.phase = 'solo'; this.notice = 'offline';
124	    this.flyers = []; this.walkers = []; this.drivers = [];
125	    this.onChange();
126	  }
127	
128	  private recv(m: ServerMsg): void {
129	    if (this.disposed) return;
130	    switch (m.t) {
131	      case 'lobby':
132	        if (this.first && this.kind === 'walk' && !Array.isArray(m.walkers)) { this.first = false; this.offline(); return; }
133	        if (this.first && this.kind === 'drive' && !Array.isArray(m.drivers)) { this.first = false; this.offline(); return; }
134	        this.flyers = m.flyers;
135	        this.walkers = Array.isArray(m.walkers) ? m.walkers : [];
136	        this.drivers = Array.isArray(m.drivers) ? m.drivers : [];
137	        if (this.first) {
138	          this.first = false;
139	          if (this.peers.length >= this.cap) this.phase = 'watching';
140	          else this.phase = 'lobby';
141	        }
142	        // đang giữ chỗ: danh sách chỉ để hiển thị
143	        this.fixWatched();
144	        break;
145	      case 'joined':
146	        /* Xe máy: máy chủ cũ (trước D-040) không vọng veh và coi mình là ô tô (khách khác thấy một chiếc ô tô): trả chỗ rồi lái một mình như máy chủ không hiểu lái xe */
147	        if (this.kind === 'drive' && this.veh === 1 && typeof m.veh !== 'number') { this.t?.send({ t: 'leave' }); this.offline(); return; }
148	        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
149	        this.fixWatched();
150	        break;
151	      case 'rejected':
152	        if (m.why === 'name') this.notice = 'nameBad';
153	        else {
154	          this.notice = 'late';   // giành trước khi đang xem, hoặc ngay ở sảnh (chỗ cuối vừa có người lúc bấm): đều báo lý do
155	          this.phase = 'watching';
156	          this.fixWatched();
157	        }
158	        break;
159	      case 'pos':
160	        this.onPos(m.f);
161	        if (Array.isArray(m.w)) this.onWalkPos(m.w);
162	        if (Array.isArray(m.d)) this.peersDrive(m.d);
163	        return;
164	      case 'released':
165	        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
166	        break;
167	    }
168	    this.onChange();
169	  }
170	}
