1	/* ===== Dù lượn nhiều người: định dạng tin khách ⇄ máy chủ (JSON) ===== */
2	import { multiParams } from './params';
3	
4	export type ClientMsg =
5	  | { t: 'join'; name: string; kind?: 'walk' | 'drive'; ch?: number; veh?: number }   // kind: 'walk' = xin chỗ đi dạo, 'drive' = chỗ lái xe; không có = chỗ bay (khách cũ). ch: nhân vật (0 nam, 1 nữ) của người đi dạo hoặc người đi xe máy; khách cũ không gửi = nam. veh: 1 = xe máy, chỉ kèm kind 'drive'; không có = ô tô (khách cũ)
6	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; bank: number; ts?: number }   // ts: giờ gửi theo đồng hồ của khách (ms); máy chủ cũ bỏ qua
7	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; pose: number; ts?: number }   // người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh), không có bank
8	  | { t: 'pos'; x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }   // người lái: v tốc độ có dấu (m/s), st góc lái (rad; xe máy: bkLeanToWire(độ nghiêng)); không có bank / pose
9	  | { t: 'hb' }
10	  | { t: 'leave' }
11	  | { t: 'chat'; text: string; id: number };   // D-041: tin chat; id do khách đếm để ghép với chatAck. Người nhận do máy chủ tính theo khoảng cách, không có trường "gửi cho ai"
12	
13	/* Lý do máy chủ từ chối tin chat: không giữ chỗ / gửi quá nhanh / rỗng sau khi làm sạch / có từ tục */
14	export type ChatWhy = 'slot' | 'rate' | 'empty' | 'bad';
15	
16	export interface Flyer { slot: number; name: string; ch?: number; veh?: number }   // ch: nhân vật của người đi dạo / người đi xe máy (walkers, drivers; máy chủ cũ không gửi = nam); veh: loại xe (chỉ drivers; 1 xe máy, máy chủ cũ không gửi = ô tô)
17	
18	/* Nhân vật đi dạo hợp lệ: 1 = nữ, mọi giá trị khác (không có, khách / máy chủ cũ, số lạ) = 0 nam */
19	export function exCharNorm(v: unknown): number { return v === 1 ? 1 : 0; }
20	
21	/* Loại xe hợp lệ của chỗ lái: 1 = xe máy, mọi giá trị khác (không có, khách / máy chủ cũ, số lạ) = 0 ô tô */
22	export function exVehNorm(v: unknown): number { return v === 1 ? 1 : 0; }
23	
24	/* Độ nghiêng xe máy qua trường st: máy chủ kẹp st ở ±drive.steerMax (0,56 rad, góc lái ô tô) nên gửi lean × BK_WIRE (độ nghiêng 0,7 rad vẫn lọt), bên nhận chia lại.
25	   Khách cũ thấy xe máy thành ô tô bẻ lái theo st (chấp nhận, spec §17.4). Số lạ (NaN) → 0 */
26	export const BK_WIRE = 0.8;
27	export function bkLeanToWire(lean: number): number {
28	  const w = lean * BK_WIRE, m = multiParams.drive.steerMax;
29	  return w > m ? m : w < -m ? -m : w === w ? w : 0;
30	}
31	export function bkLeanFromWire(st: number): number { return st === st ? st / BK_WIRE : 0; }
32	
33	export type Kind = 'fly' | 'walk' | 'drive';
34	
35	// f: mỗi phần tử [slot, x, y, z, yaw, bank, giờ gửi (ms)]; chỉ gồm slot có vị trí mới. Giờ gửi = ts của khách, khách cũ không gửi ts thì là giờ máy chủ nhận;
36	// mỗi slot một trục giờ riêng, khách nhận tự quy đổi. Máy chủ cũ (trước bản sửa giật) gửi 6 phần tử và phát lại vị trí cũ của mọi slot: khách mới nhận được cả hai dạng.
37	// Đi dạo: lobby thêm walkers (flyers chỉ có người bay; mỗi người đi dạo kèm ch = nhân vật họ chọn, nên máy vào sau cũng biết ngay từ lobby đầu), pos thêm w (mỗi phần tử [slot, x, y, z, yaw, pose, giờ gửi]; f luôn có, có thể rỗng); khách cũ bỏ qua trường lạ
38	// Lái xe: lobby thêm drivers, pos thêm d (mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]); máy chủ cũ không gửi drivers, khách mới thấy vậy thì lái một mình
39	// Xe máy (D-040): drivers kèm veh + ch, joined kind 'drive' luôn vọng veh; máy chủ cũ không vọng veh thì khách xe máy trả chỗ và lái một mình
40	// Chat (D-041): lobby kèm chat 1 khi máy chủ biết chat (máy chủ cũ không có ⇒ khách ẩn chat); chat gửi riêng tới từng người nhận, k / slot / name lấy từ kết nối người gửi;
41	// chatAck chỉ tới người gửi: n = số người đã nhận (có thể 0) hoặc why khi bị từ chối. Khách cũ bỏ qua trường lạ và tin lạ
42	export type ServerMsg =
43	  | { t: 'lobby'; flyers: Flyer[]; walkers?: Flyer[]; drivers?: Flyer[]; chat?: 1 }
44	  | { t: 'chat'; k: Kind; slot: number; name: string; text: string }
45	  | { t: 'chatAck'; id: number; n?: number; why?: ChatWhy }
46	  | { t: 'joined'; slot: number; kind?: 'walk' | 'drive'; veh?: number }
47	  | { t: 'rejected'; why: 'full' | 'name'; kind?: 'walk' | 'drive' }
48	  | { t: 'pos'; f: number[][]; w?: number[][]; d?: number[][] }   // d: [slot, x, y, z, yaw, v, st, giờ gửi]
49	  | { t: 'released' };
50	
51	// Ký tự trông như khoảng trống dù thuộc nhóm chữ/ký hiệu (chữ đệm Hangul, chữ nổi trống, nguyên âm ẩn Khmer): không tính là chữ thấy được
52	const BLANK = /[\u115F\u1160\u3164\uFFA0\u2800\u17B4\u17B5]/gu;
53	const VISIBLE = /[\p{L}\p{N}\p{S}\p{P}]/u;
54	
55	/* Bỏ ký tự điều khiển và bidi/định dạng (giữ U+200D để ghép emoji), cắt khoảng trắng.
56	   null nếu: rỗng; không có chữ/số/ký hiệu/dấu câu nào thấy được; quá nameMax grapheme; một grapheme quá graphemeCpMax code point (chồng dấu); tổng quá nameCpMax code point */
57	export function exSanitizeName(raw: string): string | null {
58	  if (typeof raw !== 'string') return null;
59	  const s = raw.replace(/[\p{Cc}\p{Cf}]/gu, c => (c === '\u200D' ? c : '')).trim();
60	  if (!s || !VISIBLE.test(s.replace(BLANK, ''))) return null;
61	  const seg = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
62	  let n = 0, cps = 0;
63	  for (const g of seg.segment(s)) {
64	    let k = 0;
65	    for (const _ of g.segment) k++;
66	    cps += k;
67	    if (++n > multiParams.nameMax || k > multiParams.graphemeCpMax || cps > multiParams.nameCpMax) return null;
68	  }
69	  return s;
70	}
71	
72	/* ===== Chat (D-041): làm sạch chữ tin nhắn, khách và máy chủ dùng chung ===== */
73	const MARKS = new RegExp('(\\p{M}{' + multiParams.chat.marksMax + '})\\p{M}+', 'gu');   // dãy dấu chồng dài hơn marksMax
74	
75	/* Chỉ nhận chuỗi; \r\n → \n, tab → khoảng trắng; bỏ ký tự điều khiển (giữ \n), surrogate lẻ (JSON.stringify nở mỗi cái thành 6 ký tự) và định dạng / bidi (giữ ZWJ U+200D ghép emoji, ZWNJ U+200C của hi / fa);
76	   dồn dấu chồng còn marksMax; giữ linesMax dòng (phần sau nối bằng khoảng trắng); cắt textMax code point; cắt khoảng trắng hai đầu. null nếu không còn ký tự thấy được */
77	export function exSanitizeChat(raw: unknown): string | null {
78	  if (typeof raw !== 'string') return null;
79	  const C = multiParams.chat;
80	  let s = raw.replace(/\r\n?/g, '\n').replace(/\t/g, ' ')
81	    .replace(/[\p{Cc}\p{Cf}\p{Cs}]/gu, c => (c === '\n' || c === '\u200D' || c === '\u200C' ? c : ''))
82	    .replace(MARKS, '$1')
83	    .trim();
84	  const lines = s.split('\n');
85	  if (lines.length > C.linesMax) s = lines.slice(0, C.linesMax - 1).join('\n') + '\n' + lines.slice(C.linesMax - 1).join(' ');
86	  s = Array.from(s).slice(0, C.textMax).join('').trim();
87	  return s && VISIBLE.test(s.replace(BLANK, '')) ? s : null;
88	}
